import json
from datetime import datetime, date
from app.extensions import db


class Recommendation(db.Model):
    """Personalized health and wellness recommendations generated by ML or fallback engine."""
    __tablename__ = "recommendations"

    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey("users.id"), nullable=False, index=True)
    date = db.Column(db.Date, nullable=False, default=date.today, index=True)
    
    category = db.Column(db.String(60), nullable=False)
    # e.g., 'activity_boost', 'sleep_hygiene', 'hydration_focus', 'metabolic_balance', 'strength_endurance', 'active_recovery'
    
    diet_guidance_json = db.Column(db.Text, nullable=False, default="{}")
    exercise_guidance_json = db.Column(db.Text, nullable=False, default="{}")
    hydration_target_liters = db.Column(db.Float, nullable=False, default=2.5)
    sleep_target_hours = db.Column(db.Float, nullable=False, default=7.5)
    daily_tasks_json = db.Column(db.Text, nullable=False, default="[]")
    
    # Traceability and Explainability
    explanation = db.Column(db.Text, nullable=False)
    confidence = db.Column(db.Float, nullable=True)
    
    # Provenance and Model Health
    model_name = db.Column(db.String(60), nullable=False, default="RecommendationModel")
    model_version = db.Column(db.String(30), nullable=False, default="v1.0.0")
    is_fallback = db.Column(db.Boolean, default=False)
    fallback_level = db.Column(db.String(40), default="none")  # none, level_2_prev_ml, level_3_deterministic, level_4_generic
    
    trace_features_json = db.Column(db.Text, default="{}")
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    def get_diet_guidance(self) -> dict:
        try:
            return json.loads(self.diet_guidance_json)
        except Exception:
            return {}

    def get_exercise_guidance(self) -> dict:
        try:
            return json.loads(self.exercise_guidance_json)
        except Exception:
            return {}

    def get_daily_tasks(self) -> list:
        try:
            return json.loads(self.daily_tasks_json)
        except Exception:
            return []

    def get_trace_features(self) -> dict:
        try:
            return json.loads(self.trace_features_json)
        except Exception:
            return {}

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "user_id": self.user_id,
            "date": self.date.isoformat() if self.date else None,
            "category": self.category,
            "diet_guidance": self.get_diet_guidance(),
            "exercise_guidance": self.get_exercise_guidance(),
            "hydration_target_liters": self.hydration_target_liters,
            "sleep_target_hours": self.sleep_target_hours,
            "daily_tasks": self.get_daily_tasks(),
            "explanation": self.explanation,
            "confidence": round(self.confidence, 3) if self.confidence is not None else None,
            "model_name": self.model_name,
            "model_version": self.model_version,
            "is_fallback": self.is_fallback,
            "fallback_level": self.fallback_level,
            "trace_features": self.get_trace_features(),
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
